using System.Text;

namespace Invoicing;

/// <summary>Renders an invoice to a plain-text document.</summary>
public sealed class InvoiceRenderer
{
    public string Render(Invoice invoice, Account account)
    {
        var builder = new StringBuilder();

        AppendHeader(builder, invoice, account);
        var (net, vat) = AppendInvoiceLines(builder, invoice);
        AppendTotals(builder, net, vat, account);
        AppendPaymentTerms(builder, account);

        return builder.ToString();
    }

    private static void AppendHeader(StringBuilder builder, Invoice invoice, Account account)
    {
        builder.AppendLine($"INVOICE {invoice.Number}");
        if (account.Name.Length > 0)
            builder.AppendLine(account.Name);

        switch (account.Kind)
        {
            case AccountKind.Business:
                builder.AppendLine("VAT registered");
                break;
            case AccountKind.Government:
                builder.AppendLine("Government purchase order");
                break;
            case AccountKind.Consumer:
                builder.AppendLine("Consumer");
                break;
        }
    }

    private static (decimal Net, decimal Vat) AppendInvoiceLines(
        StringBuilder builder,
        Invoice invoice)
    {
        decimal net = 0m;
        decimal vat = 0m;

        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount < 0m)
                continue;

            decimal lineVat = line.NetAmount * line.VatRate;
            AppendInvoiceLine(builder, line.Description, line.NetAmount, line.VatRate, lineVat);

            net += line.NetAmount;
            vat += lineVat;

            if (line.Description.Length > 40)
                builder.AppendLine("  (description truncated)");
        }

        return (net, vat);
    }

    private static void AppendInvoiceLine(
        StringBuilder builder,
        string description,
        decimal netAmount,
        decimal vatRate,
        decimal vatAmount)
    {
        if (vatRate == 0m)
            builder.AppendLine($"{description} {netAmount} (zero-rated)");
        else if (vatRate >= 0.2m)
            builder.AppendLine($"{description} {netAmount} (std {vatAmount})");
        else
            builder.AppendLine($"{description} {netAmount} (reduced {vatAmount})");
    }

    private static void AppendTotals(
        StringBuilder builder,
        decimal net,
        decimal vat,
        Account account)
    {
        decimal discount = CalculateDiscount(net, account.Kind);
        decimal gross = net + vat - discount;
        if (gross < 0m)
            gross = 0m;

        builder.AppendLine($"NET {net} VAT {vat} DISC {discount} TOTAL {gross}");
    }

    private static decimal CalculateDiscount(decimal net, AccountKind accountKind)
    {
        if (net > 1000m && accountKind == AccountKind.Business)
            return net * 0.05m;
        if (net > 5000m)
            return net * 0.10m;
        return 0m;
    }

    private static void AppendPaymentTerms(StringBuilder builder, Account account)
    {
        if (account.Kind == AccountKind.Government)
            builder.AppendLine("Remit within 30 days");
        else
            builder.AppendLine("Remit within 14 days");
    }
}
